{"command": "cd /workspace && cat > work/compose.py <<'PYEOF'
# -*- coding: utf-8 -*-
"""Keygen tune composer: builds the FT2 module via the tool bridge.
Levels: sample volume = 64 for all; every note carries a volume-column value
        = 16 + round(LV[ins] * accent/64 * GAIN)   (accent 0..64, 64 = full)
"""
import sys, os, re
sys.path.insert(0,'/workspace/work')
from ft2lib import call, batch

SMP='/workspace/work/smp'
GAIN = 0.90

INSTR = [  # (name, wavfile, panning)
 ('kick',   'kick',   128), ('snare','snare',120), ('hatc','hatc',150), ('hato','hato',152),
 ('shaker','shaker',104), ('crash','crash',138), ('riser','riser',128), ('bass','bass',128),
 ('stabmin','stabmin',116),('stabmaj','stabmaj',116),('stabm7','stabm7',116),('stabj7','stabj7',116),
 ('padmin','padmin',132),('padmaj','padmaj',124),('lead','lead',118), ('lead2','lead2',140),
 ('pluck','pluck',146), ('bell','bell',100),
]
IN   = {n:i+1 for i,(n,_,_) in enumerate(INSTR)}
# LV = displayed volume-column value at accent 64 (instrument balance)
LV = {'kick':44,'snare':36,'hatc':26,'hato':26,'shaker':13,'crash':26,'riser':24,
      'bass':34,'stabmin':24,'stabmaj':24,'stabm7':24,'stabj7':24,
      'padmin':16,'padmaj':16,'lead':32,'lead2':26,'pluck':18,'bell':13}
LVN = {IN[k]:v for k,v in LV.items()}

NPAT, NCH, ROWS, BPM, SPEED, LOOP = 15, 10, 64, 112, 4, 2

SEM = {'C':0,'C#':1,'Db':1,'D':2,'D#':3,'Eb':3,'E':4,'F':5,'F#':6,'Gb':6,'G':7,'G#':8,'Ab':8,'A':9,'A#':10,'Bb':10,'B':11}
def midi(name):
    m=re.match(r'^([A-G])([#b]?)(-?\d+)$',name)
    return 12*(int(m.group(3))+1)+SEM[m.group(1)]+(1 if m.group(2)=='#' else -1 if m.group(2)=='b' else 0)
def xm(m): return m-11
SCALE3={'A':'F','B':'G','C':'A','D':'B','E':'C','F':'D','G':'E','G#':'E'}
def harm3(m):
    nm=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'][m%12]
    tgt=SCALE3.get(nm)
    if tgt is None: return m-3
    for d in (3,4):
        if (m-d)%12==SEM[tgt]: return m-d
    return m-3

