def drums_groove(P,bars=range(4),snare=True,kick=True,hatc_beats=True,hato=True):
    for b in bars:
        o=16*b
        for r in (0,4,8,12):
            if kick: put(P,6,o+r,ins=K,note=49)
            if hatc_beats: put(P,8,o+r,ins=HC,note=49,vol=48)
        if snare:
            for r in (4,12): put(P,7,o+r,ins=S,note=49)
        if hato:
            for r in (2,6,10,14): put(P,8,o+r,ins=HO,note=49,vol=55)

def drums_sixteens(P,bars,shaker=False):
    for b in bars:
        o=16*b
        for r in range(16):
            v = 56 if r%4==0 else (44 if r%2==0 else 26)
            put(P,8,o+r,ins=HC,note=49,vol=v)
        for r in (2,6,10,14): put(P,8,o+r,ins=HO,note=49,vol=55)
        for r in (0,4,8,12): put(P,6,o+r,ins=K,note=49)
        for r in (4,12): put(P,7,o+r,ins=S,note=49)
        if shaker:
            for r in (1,3,5,7,9,11,13,15): put(P,9,o+r,ins=SH,note=49,vol=40)

def bass16(P,chords,octaves=True,vol=(64,52,40)):
    for b,c in enumerate(chords):
        o=16*b; root=CH[c]['bass']
        for r in range(16):
            n = root if r%2==0 else (root+12 if octaves else root)
            v = vol[0] if r%4==0 else (vol[1] if r%2==0 else vol[2])
            put(P,2,o+r,ins=BS,note=xm(n),vol=v)

def bass8(P,chords,push=True):
    for b,c in enumerate(chords):
        o=16*b; root=CH[c]['bass']
        for r in (0,2,4,6,8,10,12,14):
            put(P,2,o+r,ins=BS,note=xm(root),vol=64 if r%4==0 else 50)
        if push:
            put(P,2,o+5, ins=BS,note=xm(root+12),vol=40)
            put(P,2,o+13,ins=BS,note=xm(root+12),vol=40)

def stabs(P,chords,vol=48,hi=False,hirows=(0,8),hivol=40):
    for b,c in enumerate(chords):
        o=16*b; t,n=CH[c]['stab']
        for r in (2,6,10,14): put(P,3,o+r,ins=STABINS[t],note=xm(n),vol=vol)
        if hi:
            t2,n2=CH[c]['hi']
            for r in hirows: put(P,5,o+r,ins=STABINS[t2],note=xm(n2),vol=hivol)

def arp16(P,chords,ch=4,mode='up',vol=52,shift=0):
    for b,c in enumerate(chords):
        o=16*b; a=CH[c]['arp']
        if mode=='up':    seq=[a[i%4]+shift for i in range(16)]
        elif mode=='down':seq=[a[3-(i%4)]+shift for i in range(16)]
        else:
            s=[0,1,2,3,2,1,0,1,2,3,2,1,0,1,2,3]; seq=[a[s[i]]+shift for i in range(16)]
        for r in range(16):
            put(P,ch,o+r,ins=IN['pluck'],note=xm(seq[r]),vol=min(64,vol+10) if r%4==0 else vol)

def arp8(P,chords,ch=4,vol=46):
    for b,c in enumerate(chords):
        o=16*b; a=CH[c]['arp']; s=[0,2,1,2,3,2,1,2]
        for i,r in enumerate(range(0,16,2)):
            put(P,ch,o+r,ins=IN['pluck'],note=xm(a[s[i%8]]),vol=vol+8 if i%2==0 else vol)

def pads(P,chords,bar_rows=(0,32),vol=50,chans=(3,4,5)):
    for br,c in zip(bar_rows, chords[::2]):
