def parse_mel(s):
    s=s.replace('|',' '); toks=s.split(); out=[]; pos=0
    for t in toks:
        n,d=(t.split(':') if ':' in t else (t,2))
        d=int(d)
        if n!='r': out.append((pos,midi(n),d))
        pos+=d
    assert pos==64,"melody len %d != 64: %r"%(pos,s)
    return out

def lead(P,mel,ch=0,ins='lead',vol=60,acc=64,vib=True,vibp=0x48,harm=False,hvol=48):
    for row,m,d in mel:
