# -*- coding: utf-8 -*-
"""Keygen tune composer: builds the FT2 module via the tool bridge.
Levels: sample volume = 64 for all; every note carries a volume-column value
        = 16 + round(LV[ins] * accent/64 * GAIN)   (accent 0..64, 64 = full)
"""
import sys, os, re
sys.path.insert(0,'/workspace/work')
from ft2lib import call, batch

SMP='/workspace/work/smp'
GAIN = 0.90

INSTR = [  # (name, wavfile, panning)
